    add_screenshot_marker(doc, "Параллельный показ интерфейса в трёх типовых разрешениях экрана: 1920×1080 (десктоп), 1024×768 (планшет), 375×812 (смартфон)")
    add_figure_caption(doc, "Рисунок 4.3 — Кроссустройственное тестирование")

    add_section_heading(doc, "4.4.", "Тестирование транзакционности и устойчивости к сбоям")
    add_paragraph(doc,
        "Тестирование транзакционности направлено на "
        "проверку выполнения свойства атомарности при "
        "имитации внезапного прерывания процесса между "
        "промежуточными SQL-операциями алгоритма закрытия. "
        "Методика испытания заключается в патчинге кода "
        "обработчика: между списанием со склада и "
        "обновлением статуса заявки искусственно "
        "выбрасывается RuntimeError, после чего проверяется "
        "состояние базы данных.")

    add_paragraph(doc, "Сценарии тестирования транзакционности:")
    for item in [
        "сбой после INSERT в request_parts, до UPDATE "
        "spare_parts — ожидается полный откат, "
        "request_parts пуст, остаток детали не изменён;",
        "сбой после UPDATE одного spare_parts, до "
        "UPDATE второго — ожидается откат обеих "
        "операций, остатки обеих деталей не "
        "изменены;",
        "сбой между списанием и UPDATE статуса заявки "
        "— ожидается откат списания, статус остаётся "
        "«В работе»;",
        "сбой триггера trg_request_status_audit "
        "(имитация переполнения) — ожидается откат "
        "смены статуса.",
    ]:
        add_list_item(doc, item)

    add_paragraph(doc,
        "Все четыре сценария показали корректное "
        "поведение системы: после имитации сбоя база "
        "данных остаётся в согласованном состоянии "
        "без частично применённых изменений. Это "
        "подтверждает корректность реализации "
        "ACID-свойства атомарности через контекстный "
        "менеджер db_cursor с автоматическим "
        "rollback при исключении.")

    add_paragraph(doc,
        "Дополнительно проведены тесты "
        "восстановления после прерывания "
        "выполнения SQLite-транзакции на "
        "уровне операционной системы: "
        "процесс приложения принудительно "
        "завершается во время commit() с "
        "помощью kill -KILL. WAL-журнал "
        "SQLite при следующем запуске "
        "сервера корректно восстанавливает "
        "состояние: либо транзакция была "
        "успешно зафиксирована до прерывания "
        "(все изменения присутствуют), либо "
        "была не завершена (все изменения "
        "откатываются). Промежуточных "
        "состояний за 50 тестовых прогонов "
        "не зафиксировано, что подтверждает "
        "защищённость данных от "
        "технических сбоев.")

    add_paragraph(doc,
        "Свойство Durability (стойкость) "
        "подтверждено через тест с "
        "имитацией исчерпания дискового "
        "пространства: при заполнении "
        "диска до 99% сервер корректно "
        "возвращает 500 Internal Server "
        "Error и не пытается сохранять "
        "повреждённые данные. После "
        "освобождения дискового "
        "пространства работа "
        "автоматически восстанавливается, "
        "целостность базы сохранена. "
        "Этот тест важен для эксплуатации "
        "в условиях ограниченных "
        "ресурсов промышленного сервера.")

    add_section_heading(doc, "4.5.", "Тестирование производительности")
